function backupDialog(){if(!requireUnlocked())return;const box=modal('Encrypted backup and restore');box.append(el('p','Account autosave stores encrypted revisions. A downloaded backup is an additional copy protected by the separate password below. Restoring creates a new saved account revision; it does not silently replace another tab’s changes.'));const pw=labeled(box,'Backup password (12–128 characters)','password'),status=el('p');button(box,'Download encrypted backup',async()=>{try{const b=await encryptBackup({data:state.data,step:state.step},pw.value);download(new Blob([b],{type:'application/json'}),'chargeready-private.arrival');status.textContent='Backup downloaded. Keep its password separately.';}catch(e){status.textContent=e.message;}});const file=labeled(box,'Choose a .arrival backup','file');file.accept='.arrival,application/json';button(box,'Unlock backup & review replacement',async()=>{try{if(!file.files[0]||file.files[0].size>220000)throw Error('Choose a backup under 220 KB.');const restored=await decryptBackup(await file.files[0].text(),pw.value);const clean=await request('/api/validate',{application_id:state.app.id,data:restored.data});confirmChange('Restore this backup into the current application?',async()=>{state.data=clean.data;state.step=0;initializeData();changed();await workspace.flush();render();});}catch(e){status.textContent=e.name==='OperationError'?'Incorrect backup password or damaged file.':e.message;}});box.append(status);}
