function chooseEvidence(record,input){const box=modal('Choose supporting documents');box.append(el('p','Choose documents that support this answer. If your list is empty, add documents in “Your supporting documents” first.'));const selected=new Set((record.refs||'').split(/[,\s]+/).filter(Boolean)),checks=[];for(const e of state.data.sections.evidence||[]){if(!e.id||e.id===record.id)continue;const c=consent(box,(e.title||'Untitled document')+' · '+(e.status||'Unknown'));c.checked=selected.has(e.id);checks.push([c,e.id]);}button(box,'Link these documents',()=>{record.refs=checks.filter(([c])=>c.checked).map(([,id])=>id).join(',');input.value=record.refs;changed();closeModal();},'primary');}
